# Test yyyyy SimpleDateFormat behavior
cd /tmp && cat > T.java << 'EOF'
import java.text.*;
import java.util.*;
public class T {
  public static void main(String[] args) throws Exception {
    // UUID
    String p = "^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{11}$";
    String u = java.util.UUID.randomUUID().toString();
    System.out.println("uuid "+u+" match "+u.matches(p));
    String p2 = "^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$";
    System.out.println("uuid fixed match "+u.matches(p2));

    // timestamp yyyyy
    SimpleDateFormat sdf = new SimpleDateFormat("yyyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
    sdf.setTimeZone(TimeZone.getTimeZone("UTC"));
    String ts = "2024-08-05T13:47:00.000Z";
    try {
      Date d = sdf.parse(ts);
      System.out.println("yyyyy parse: "+d+" -> "+sdf.format(d));
    } catch(Exception e) { System.out.println("yyyyy fail: "+e); }

    SimpleDateFormat sdf2 = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
    sdf2.setTimeZone(TimeZone.getTimeZone("UTC"));
    Date d2 = sdf2.parse(ts);
    System.out.println("yyyy parse: "+d2);

    // Customer pattern
    String cp = "^[01-9a-zA-Z]+@[a-zA-Z]+[-][a-zA-Z]+";
    String[] samples = {"9999999999@AA-Name","user@finvu","999@aa-bank","test@AA-NAME","91XXXXXXXXXX@nadl-aa","a@b-c","123@ab-cd","x@y-zextra","9999999999@AAName"};
    for (String s: samples) System.out.println(s+" -> "+s.matches(cp));

    // joda hh
    org.joda.time.format.DateTimeFormatter f = org.joda.time.format.DateTimeFormat.forPattern("yyyy-MM-dd'T'hh:mm:ss.SSS'Z'");
    org.joda.time.DateTime dt = new org.joda.time.DateTime(2024,8,5,13,47,0, org.joda.time.DateTimeZone.UTC);
    System.out.println("joda hh: "+dt.toString(f));
    org.joda.time.format.DateTimeFormatter f2 = org.joda.time.format.DateTimeFormat.forPattern("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
    System.out.println("joda HH: "+dt.toString(f2));
  }
}
EOF
